const MASTER = "pb-bella-1060d0b90a2d";
const q = $('Página').first().json.query || {};
const rows = $json.values || [];
const hoje = new Date().toISOString().slice(0, 10);
let user = null;
if (q.t === MASTER) user = { nome: 'Eduardo', papel: 'ADMIN', obra: '' };
else if (q.t) {
  const r = rows.find(r => r[4] === q.t && String(r[6]).toUpperCase() === 'TRUE' && (!r[5] || r[5] >= hoje));
  if (r) user = { nome: r[1] || 'você', papel: r[2] || '', obra: r[3] || '' };
}
const html = user
  ? "<!DOCTYPE html>
<html lang="pt-BR">
<meta charset="utf-8">
<title>Bella — Prisbel Construtora (v0.6 — ao vivo)</title>
<meta name="viewport" content="width=device-width, initial-scale=1">
<script>const BELLA_USER = __BELLA_USER__;</script>
<style>
  /* ---------- tokens: linguagem visual Gemini ---------- */
  :root{
    --bg:#ffffff; --side:#f0f4f9; --side-hov:#dde3ea; --surf:#f0f4f9;
    --ink:#1f1f1f; --ink-2:#444746; --ink-3:#5f6368; --line:#e3e3e3;
    --user-bub:#f0f4f9; --brand:#22219B; --g1:#22219B; --g2:#5B5BE8; --g3:#9B72CB;
    --amber:#E8A33D; --warn:#B3261E; --ok:#146C43;
  }
  @media (prefers-color-scheme: dark){:root{
    --bg:#131314; --side:#1e1f20; --side-hov:#2d2f31; --surf:#1e1f20;
    --ink:#e3e3e3; --ink-2:#c4c7c5; --ink-3:#9aa0a6; --line:#444746;
    --user-bub:#333537; --brand:#a8a7f0; --g1:#8B8AF0; --g2:#A9A7FF; --g3:#C9A6E9;
    --warn:#F2B8B5; --ok:#6DD58C;
  }}
  :root[data-theme="dark"]{
    --bg:#131314; --side:#1e1f20; --side-hov:#2d2f31; --surf:#1e1f20;
    --ink:#e3e3e3; --ink-2:#c4c7c5; --ink-3:#9aa0a6; --line:#444746;
    --user-bub:#333537; --brand:#a8a7f0; --g1:#8B8AF0; --g2:#A9A7FF; --g3:#C9A6E9;
    --warn:#F2B8B5; --ok:#6DD58C;
  }
  :root[data-theme="light"]{
    --bg:#ffffff; --side:#f0f4f9; --side-hov:#dde3ea; --surf:#f0f4f9;
    --ink:#1f1f1f; --ink-2:#444746; --ink-3:#5f6368; --line:#e3e3e3;
    --user-bub:#f0f4f9; --brand:#22219B; --g1:#22219B; --g2:#5B5BE8; --g3:#9B72CB;
    --warn:#B3261E; --ok:#146C43;
  }

  *{box-sizing:border-box;margin:0}
  html,body{height:100%}
  body{
    font-family:"Google Sans","Product Sans",Roboto,"Segoe UI",system-ui,sans-serif;
    background:var(--bg); color:var(--ink);
    display:flex; height:100dvh; overflow:hidden; font-size:16px; line-height:1.5;
    -webkit-font-smoothing:antialiased;
  }
  button{font:inherit;color:inherit;background:none;border:none;cursor:pointer}
  svg{display:block}
  :focus-visible{outline:2px solid var(--g2);outline-offset:2px;border-radius:8px}

  /* ---------- sidebar ---------- */
  aside{
    width:280px;flex-shrink:0;background:var(--side);
    display:flex;flex-direction:column;padding:12px 10px;gap:4px;
  }
  .icon-btn{
    width:44px;height:44px;border-radius:50%;display:grid;place-items:center;color:var(--ink-2)
  }
  .icon-btn:hover{background:var(--side-hov)}
  .new-chat{
    display:flex;align-items:center;gap:12px;margin:14px 4px 22px;padding:12px 20px 12px 16px;
    border-radius:999px;background:var(--side-hov);font-size:.9rem;font-weight:500;color:var(--ink-2);
    width:fit-content
  }
  .new-chat:hover{filter:brightness(.96)}
  .side-label{font-size:.8rem;font-weight:600;color:var(--ink-2);padding:10px 16px 6px;letter-spacing:.2px}
  nav{display:flex;flex-direction:column;gap:2px;overflow-y:auto}
  .conv{
    display:flex;align-items:center;gap:12px;padding:10px 16px;border-radius:999px;
