    white-space:nowrap;overflow:hidden;text-overflow:ellipsis
  }
  .conv:hover{background:var(--side-hov)}
  .conv .txt{overflow:hidden;text-overflow:ellipsis}
  .conv .dot{width:8px;height:8px;border-radius:50%;background:var(--amber);flex-shrink:0}
  .side-foot{margin-top:auto;display:flex;align-items:center;gap:12px;padding:12px 14px}
  .av{
    width:32px;height:32px;border-radius:50%;background:linear-gradient(135deg,var(--g1),var(--g3));
    color:#fff;display:grid;place-items:center;font-size:.78rem;font-weight:600;flex-shrink:0
  }
  .side-foot b{font-size:.86rem;font-weight:500;display:block}
  .side-foot span{font-size:.76rem;color:var(--ink-3)}

  /* ---------- main ---------- */
  main{flex:1;display:flex;flex-direction:column;min-width:0}
  header{display:flex;align-items:center;gap:8px;padding:10px 18px}
  #menu-btn{display:none}
  .word{font-size:1.35rem;font-weight:500;color:var(--ink-2);letter-spacing:-.2px;padding-left:4px}
  .model-chip{
