  }
  .model-chip:hover{background:var(--side-hov)}
  .model-chip label{font-size:.7rem;letter-spacing:.08em;color:var(--ink-3);font-weight:600}
  .model-chip select{border:none;background:transparent;font:inherit;font-weight:500;color:inherit;cursor:pointer;outline:none}
  header .right{margin-left:auto;display:flex;align-items:center;gap:6px}
  .bell{position:relative}
  .bell i{
    position:absolute;top:6px;right:6px;width:8px;height:8px;border-radius:50%;
    background:var(--amber);border:2px solid var(--side);font-style:normal
  }

  #chat{flex:1;overflow-y:auto;padding:0 20px}
  .wrap{max-width:760px;margin:0 auto;width:100%}

  /* ---------- saudação (empty state) ---------- */
  #hello{padding:12vh 0 0}
  #hello h1{
    font-size:clamp(2.2rem,5.6vw,3.4rem);font-weight:500;letter-spacing:-1px;line-height:1.12;
    background:linear-gradient(90deg,var(--g1),var(--g2) 45%,var(--g3));
    -webkit-background-clip:text;background-clip:text;color:transparent;text-wrap:balance
  }
  #hello p{font-size:clamp(1.5rem,4vw,2.1rem);font-weight:500;color:var(--ink-3);margin-top:2px;letter-spacing:-.5px}
  .cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:44px}
  .card{
    position:relative;background:var(--surf);border-radius:14px;padding:16px 16px 52px;
    text-align:left;font-size:.94rem;line-height:1.35;color:var(--ink-2);min-height:130px
  }
  .card:hover{background:var(--side-hov)}
  .card .ci{
    position:absolute;right:12px;bottom:12px;width:32px;height:32px;border-radius:50%;
    background:var(--bg);display:grid;place-items:center;font-size:1rem
  }

  /* ---------- mensagens ---------- */
  #thread{display:flex;flex-direction:column;gap:26px;padding:20px 0 8px}
  .msg{display:flex;gap:16px;max-width:100%}
  .msg.user{justify-content:flex-end}
  .msg.user .bubble{
    background:var(--user-bub);border-radius:22px;padding:12px 20px;max-width:78%;font-size:.98rem
  }
  .b-av{
    width:30px;height:30px;flex-shrink:0;border-radius:50%;
    background:linear-gradient(135deg,var(--g1),var(--g3));display:grid;place-items:center;margin-top:1px
  }
  .msg.bella .bubble{font-size:1rem;color:var(--ink);padding-top:3px;flex:1;min-width:0}
  .bubble ul{padding-left:22px;margin:10px 0 4px;display:flex;flex-direction:column;gap:6px}
  .bubble b{font-weight:600}
  .bubble .tag{
    display:inline-block;font-size:.72rem;font-weight:600;letter-spacing:.04em;border-radius:8px;
    padding:3px 10px;margin-top:12px;margin-right:6px
  }
  .tag.ok{background:color-mix(in srgb,var(--ok) 14%,transparent);color:var(--ok)}
  .tag.warn{background:color-mix(in srgb,var(--amber) 20%,transparent);color:var(--amber)}
  .typing{display:inline-flex;gap:5px;padding:8px 0}
  .typing i{width:8px;height:8px;border-radius:50%;background:var(--g2);animation:tp 1.2s infinite}
  .typing i:nth-child(2){animation-delay:.2s}.typing i:nth-child(3){animation-delay:.4s}
  @keyframes tp{0%,60%,100%{opacity:.3;transform:translateY(0)}30%{opacity:1;transform:translateY(-4px)}}
  @media (prefers-reduced-motion:reduce){.typing i{animation:none}}

  /* ---------- barra de entrada ---------- */
  .composer{padding:8px 20px 14px;background:var(--bg)}
  .composer .wrap{display:flex;flex-direction:column;gap:10px}
  .quick{display:flex;gap:8px;overflow-x:auto;padding-bottom:2px}
  .quick .chip{
    flex-shrink:0;background:var(--surf);border:1px solid var(--line);border-radius:999px;
    padding:8px 16px;font-size:.86rem;color:var(--ink-2);white-space:nowrap
  }
  .quick .chip:hover{background:var(--side-hov)}
  .inputbar{
    display:flex;align-items:flex-end;gap:6px;background:var(--surf);
    border-radius:30px;padding:6px 8px 6px 8px
  }
  .inputbar:focus-within{background:var(--side-hov)}
  .inputbar textarea{
    flex:1;border:none;background:transparent;font:inherit;color:inherit;resize:none;
    max-height:180px;padding:14px 6px;outline:none;line-height:1.5
  }
  .inputbar textarea::placeholder{color:var(--ink-3)}
  .mic,.send,.plus{width:44px;height:44px;border-radius:50%;display:grid;place-items:center;flex-shrink:0;color:var(--ink-2)}
  .plus:hover,.mic:hover{background:var(--bg)}
  .mic .ico-stop{display:none}
  .mic.rec{background:var(--g2);color:#fff}
  .mic.rec .ico-mic{display:none}
  .mic.rec .ico-stop{display:block;animation:pl 1.2s infinite}
  @keyframes pl{50%{opacity:.55}}
  .send{background:var(--g1);color:#fff}
  .send:disabled{background:transparent;color:var(--ink-3);opacity:.45;cursor:default}
  .disclaimer{font-size:.76rem;color:var(--ink-3);text-align:center}

  /* ---------- mobile ---------- */
  #overlay{display:none}
  @media (max-width:840px){
    aside{position:fixed;inset:0 22% 0 0;z-index:30;transform:translateX(-102%);transition:transform .22s;box-shadow:0 0 40px rgba(0,0,0,.28)}
    @media (prefers-reduced-motion:reduce){aside{transition:none}}
    aside.open{transform:none}
    #overlay.show{display:block;position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:20}
    #menu-btn{display:grid}
    #hello{padding:8vh 0 0}
    .cards{grid-template-columns:1fr 1fr;gap:10px}
    .card{min-height:118px;font-size:.88rem;padding:14px 14px 48px}
    .msg.user .bubble{max-width:88%}
    #chat{padding:0 14px}.composer{padding:8px 14px 12px}
  }
</style>

