<script>
  const $ = (s) => document.querySelector(s);
  const thread = $('#thread'), chat = $('#chat'), hello = $('#hello');
  const input = $('#input'), send = $('#send'), mic = $('#mic'), quick = $('#quick');

  const TOKEN = new URLSearchParams(location.search).get('t') || '';
  const API_URL = '/webhook/bella-chat-api';
  const historico = []; // {de:'usuario'|'bella', texto}

  const AV = '<div class="b-av" aria-hidden="true"><svg width="18" height="18" viewBox="0 0 34 34"><path d="M10 8l7 4v6l-7-4V8zm14 3l-7 4v6l7-4v-6zM10 19l7 4v6l-7-4v-6z" fill="#fff"/></svg></div>';
  function push(who, html){
    const m = document.createElement('div');
    m.className = 'msg ' + who;
    m.innerHTML = (who === 'bella' ? AV : '') + '<div class="bubble">' + html + '</div>';
    thread.appendChild(m);
    chat.scrollTop = chat.scrollHeight;
    return m;
  }
  function typing(){ return push('bella', '<span class="typing"><i></i><i></i><i></i></span>'); }
  const esc = (s) => s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  function render(texto){
    return esc(texto)
      .replace(/&lt;(\/?)(b|i|ul|li|br)&gt;/g, '<$1$2>')
      .replace(/\n/g, '<br>');
  }
  function start(){ hello.style.display = 'none'; }

  let ocupado = false;
  async function chamarAPI(body, bolhaUser, textoUser){
    const t = typing();
    try {
      const res = await fetch(API_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(Object.assign({
          t: TOKEN, obra: $('#obra').value, historico: historico.slice(-12),
        }, body)),
      });
      const data = await res.json();
      // áudio: troca a bolha do usuário pela transcrição
      if (data.transcricao && bolhaUser) {
        bolhaUser.querySelector('.bubble').innerHTML = '🎤 ' + esc(data.transcricao);
        historico.push({ de: 'usuario', texto: data.transcricao });
      } else if (textoUser) {
        historico.push({ de: 'usuario', texto: textoUser });
      }
      const resposta = data.resposta || 'Opa, me perdi aqui. Pode repetir?';
      t.querySelector('.bubble').innerHTML = render(resposta);
      historico.push({ de: 'bella', texto: resposta });
    } catch (e) {
      t.querySelector('.bubble').innerHTML =
        'Tive um problema de conexão agora. 😅 Tenta de novo em instantes, por favor.';
    }
    chat.scrollTop = chat.scrollHeight;
    ocupado = false;
  }
  async function enviar(texto){
    if (ocupado || !texto.trim()) return;
    ocupado = true; quick.hidden = true; start();
    push('user', esc(texto));
    await chamarAPI({ mensagem: texto }, null, texto);
  }

  const STARTERS = {
    pedido: 'Manda 50 sacos de cimento e um rolo de lona preta',
    status: 'Como estão os pedidos? Tem alguma pendência?',
    duvida: 'Preciso de 50 conjuntos de vaso sanitário. O que eu preciso especificar?',
    pendencia: 'Quais pedidos estão com pendência? Me ajuda a resolver.',
    preorcamento: 'Me dá um pré-orçamento, uma ideia de preço: 100 sacos de cimento, 2 toneladas de vergalhão CA50 12,5mm e 500 blocos de concreto estrutural.',
  };
  document.querySelectorAll('[data-flow]').forEach((b) =>
    b.addEventListener('click', () => {
      document.getElementById('side').classList.remove('open');
      document.getElementById('overlay').classList.remove('show');
      enviar(STARTERS[b.dataset.flow] || b.textContent.trim());
    }));

  input.addEventListener('input', () => {
    send.disabled = !input.value.trim();
    input.style.height = 'auto'; input.style.height = Math.min(input.scrollHeight, 110) + 'px';
  });
  function sendFree(){
    const v = input.value.trim(); if (!v) return;
    input.value = ''; send.disabled = true; input.style.height = 'auto';
    enviar(v);
  }
  send.addEventListener('click', sendFree);
  input.addEventListener('keydown', (e) => { if (e.key === 'Enter' && !e.shiftKey){ e.preventDefault(); sendFree(); } });

  /* ------- microfone: grava e o Gemini transcreve (estilo WhatsApp) ------- */
  let rec = null, chunks = [];
  mic.addEventListener('click', async () => {
    if (rec && rec.state === 'recording') { rec.stop(); return; }
    if (ocupado) return;
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mime = ['audio/mp4', 'audio/webm;codecs=opus', 'audio/webm']
        .find((m) => window.MediaRecorder && MediaRecorder.isTypeSupported(m)) || '';
      rec = new MediaRecorder(stream, mime ? { mimeType: mime } : undefined);
      chunks = [];
      rec.ondataavailable = (e) => { if (e.data.size) chunks.push(e.data); };
      rec.onstop = async () => {
        stream.getTracks().forEach((tr) => tr.stop());
        mic.classList.remove('rec');
        const blob = new Blob(chunks, { type: rec.mimeType || 'audio/webm' });
        if (blob.size < 2000) return; // toque acidental
        ocupado = true; quick.hidden = true; start();
        const bolha = push('user', '🎤 <i>enviando áudio…</i>');
        const b64 = await new Promise((ok) => {
          const fr = new FileReader();
          fr.onload = () => ok(String(fr.result).split(',')[1]);
          fr.readAsDataURL(blob);
        });
        await chamarAPI({ audio: { mime: blob.type.split(';')[0], data: b64 } }, bolha, null);
      };
      rec.start();
      mic.classList.add('rec');
    } catch (e) {
      push('bella', 'Não consegui acessar o microfone. Verifique a permissão do navegador (ícone de cadeado na barra de endereço) e tente de novo. 🙏');
    }
  });

  const side = $('#side'), overlay = $('#overlay');
  $('#menu-btn').addEventListener('click', () => { side.classList.add('open'); overlay.classList.add('show'); });
  overlay.addEventListener('click', () => { side.classList.remove('open'); overlay.classList.remove('show'); });
  document.querySelectorAll('aside .conv').forEach((b) => b.addEventListener('click', () => { side.classList.remove('open'); overlay.classList.remove('show'); }));

  const sideClose = $('#side-close');
  if (sideClose) sideClose.addEventListener('click', () => { side.classList.remove('open'); overlay.classList.remove('show'); });

  /* ---- personalização por usuário (ACESSOS) ---- */
  const USER = (typeof BELLA_USER === 'object' && BELLA_USER) || { nome: 'Daniela', papel: 'Compradora', obra: '' };
  (function () {
    const pn = String(USER.nome || '').trim().split(/s+/)[0] || 'você';
    const h1 = document.querySelector('#hello h1'); if (h1) h1.textContent = 'Olá, ' + pn;
    const sf = document.querySelector('.side-foot');
    if (sf) { sf.querySelector('b').textContent = USER.nome; sf.querySelector('span').textContent = USER.papel; }
    const ini = (String(USER.nome||'').trim().split(/s+/).map(w => w[0]).slice(0, 2).join('') || 'BL').toUpperCase();
    document.querySelectorAll('.av').forEach(a => a.textContent = ini);
    if (USER.obra) { const sel = document.getElementById('obra');
      const op = [...sel.options].find(o => o.value === USER.obra || o.text === USER.obra);
      if (op) sel.value = op.value; }
  })();
</script>

